INSERT INTO platforms ("id", "slug", "name", "company", "website", "logoUrl", "description", "categoryId", "primaryUse", "costTier", "difficultyLevel", "platformType", "currentPricing", "freeTierFeatures", "usageLimits", "qualityRestrictions", "upgradeTriggers", "installationType", "offlineCapable", "apiAvailable", "keyIntegrations", "privacyLevel", "idealUserTypes", "primaryUseCases", "timeToProductivity", "learningCurve", "directAlternatives", "complementaryTools", "budgetAlternativeTo", "privacyAlternativeTo", "contentTypes", "outputFormats", "languageSupport", "featured", "verified", "createdAt", "updatedAt", "hasMobileApp", "iosAppUrl", "androidAppUrl", "mobileWebFriendly") SELECT $a32$cmpipecataudit32x0000001$a32$, $a32$pipecat$a32$, $a32$Pipecat$a32$, $a32$Daily$a32$, $a32$https://pipecat.ai$a32$, NULL, $a32$An open-source Python framework for building voice and multimodal AI agents that you can talk to in real time. You pick the speech-to-text, language-model and text-to-speech services from more than 200 integrated providers, and Pipecat handles interruptions, turn detection and conversation context over WebRTC, SIP or phone (PSTN). It is free under the BSD 2-Clause license and runs wherever Python runs; Pipecat Cloud, run by Daily, is an optional paid host. Maintained by Daily: Deepgram announced on 2026-10-29 that it is acquiring Daily (announced, not completed, as of 2026-11-02) and says Pipecat will stay open source under an independent Pipecat Foundation. Your own provider accounts bill separately (as of 2026-11-02).$a32$, $a32$cmnxhfk4u004q88svb7gaw4ew$a32$, $a32$Open-source Python framework for building real-time voice and multimodal AI agents$a32$, $a32$FREEMIUM$a32$::"CostTier", $a32$INTERMEDIATE$a32$::"Difficulty", ARRAY[$a32$api$a32$, $a32$local$a32$]::text[], $a32$Free and open source (BSD 2-Clause). Optional Pipecat Cloud hosting (by Daily): agent-1x $0.01/min active ($0.0005/min reserved), agent-2x $0.02/min, agent-3x $0.03/min; WebRTC voice transport free for 1:1 sessions; telephony and recording extra; your LLM, STT and TTS providers bill separately (as of 2026-11-02)$a32$, $a32$Free and open source (BSD 2-Clause): build and run voice agents yourself at no charge; your speech, language and voice providers bill separately and Pipecat Cloud hosting is optional (as of 2026-11-02)$a32$, $a32$Pipecat Cloud: unlimited concurrency; Krisp VIVA noise filtering free up to 10,000 active session minutes a month; provider accounts have their own limits (as of 2026-11-02)$a32$, NULL, $a32$Having Daily host the agent on Pipecat Cloud (billed per active minute); phone calling over PSTN or SIP and recording; Pipecat Enterprise to run Pipecat Cloud in your own AWS, Azure or GCP account$a32$, $a32$Python package (pipecat-ai on PyPI), Python 3.11 or newer; pipecat CLI$a32$, false, false, $a32$200+ integrated speech, language and vision providers (the quickstart uses Deepgram, OpenAI and Cartesia); WebRTC, SIP and PSTN transports; client SDKs for JavaScript, React, React Native, iOS, Android and C++; Pipecat Flows$a32$, $a32$MEDIUM$a32$::"PrivacyLevel", ARRAY[$a32$Python developers$a32$, $a32$teams building voice agents$a32$, $a32$developers prototyping phone and voice assistants$a32$]::text[], $a32$Voice assistants and phone agents; real-time conversation with interruption handling; voice-and-video agents; multi-agent workflows with Pipecat Flows$a32$, NULL, $a32$Moderate$a32$, ARRAY[$a32$Vapi$a32$, $a32$Retell AI$a32$]::text[], ARRAY[$a32$Deepgram$a32$, $a32$OpenAI API$a32$, $a32$ElevenLabs$a32$]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[$a32$Audio (speech)$a32$, $a32$Text$a32$, $a32$Video$a32$]::text[], ARRAY[$a32$Real-time spoken replies$a32$, $a32$streaming audio and video sessions$a32$]::text[], $a32$Depends on the speech and language providers you connect$a32$, false, true, now(), now(), false, NULL, NULL, false WHERE NOT EXISTS (SELECT 1 FROM platforms WHERE slug = $a32$pipecat$a32$) AND EXISTS (SELECT 1 FROM categories WHERE id = $a32$cmnxhfk4u004q88svb7gaw4ew$a32$);
UPDATE platforms SET "complementaryTools" = array_append("complementaryTools", $a32$Pipecat$a32$), "updatedAt" = now() WHERE slug = $a32$deepgram$a32$ AND NOT ($a32$Pipecat$a32$ = ANY("complementaryTools"));
